export const missions=rows.map((r,i)=>({id:r[0],name:r[1],year:r[2],world:r[3],type:r[4],region:r[5],status:r[6],arrival:r[7],end:r[8],summary:r[9],family:r[10],model:'assets/'+r[11],coordinates:r[12],components:parts[r[10]==='viking2'?'viking':r[10]],image:'assets/'+r[0]+'.jpg',source:r[0]==='ds2'?'https://science.nasa.gov/mission/mars-polar-lander-deep-space-2/':sources[r[0]].source,imageSource:sources[r[0]].image_source,index:i+1,schematic:r[11].includes('schematic'),country:'Estados Unidos · NASA'})).sort((a,b)=>b.year-a.year||b.index-a.index);
export const years=[...new Set(missions.map(m=>m.year))];
const fleetCatalog=await fetch('assets/fleet/catalog.json?v=20261112inspeccion').then(r=>r.json());
tr(fleetCatalog);tr(missions);   // inglés: catálogo de piezas y datos de las misiones
function variantComponents(parts, missionId) {
 return parts.filter(part => !part.variant || part.variant === missionId)
  .map(part => ({...part, children: variantComponents(part.children || [], missionId)}));
}
for(const mission of missions){
 const baseFleet=fleetCatalog[mission.family];if(!baseFleet)continue;
 const fleet={...baseFleet,...(baseFleet.variants?.[mission.id]||{})};
 if(mission.id==='lrv17')mission.summary+=' '+t('El modelo muestra la reparación del guardabarros trasero derecho con mapas laminados, cinta y abrazaderas.');
 mission.fleet=fleet;mission.model=fleet.model;mission.schematic=mission.id==='phoenix'||!fleet.nasaBase;
 const components=fleet.excludeInspectionNodes ? variantComponents(fleet.components, mission.id) : fleet.components;
 mission.components=components.map(part=>({...part,exteriorPosition:fleet.positions[part.id]}));
}
